/* concept diagrams - generated by cloud-work jobs/dosik-rest (do not edit by hand) */
window.DOSIK=window.DOSIK||{};DOSIK["cfa_l1_ethics"]={"1":[{"t":"table","title":"Standard I(A) Knowledge of the Law","head":["Topic","Content"],"rows":[["Requirement","Standard I(A) requires members and candidates to comply with the stricter of · applicable law and the Code and Standards when the two conflict"],["Dissociation","A member or candidate who has reasonable grounds to believe a client's activity is ongoing and illegal · must dissociate from the activity if raising it directly does not stop it"],["Extreme cases","Dissociation from a colleague's or employer's violation may, in extreme cases, · require a member or candidate to leave their employment"],["Limit","Standard I(A) does not require members and candidates to become experts in every law · that could potentially apply to their professional activities"],["Products","Members and candidates involved in creating or maintaining investment products must understand and comply with · applicable laws and regulations in all relevant jurisdictions where those products are sold or originated"],["Candidates","CFA candidates who are not CFA Institute members are bound by the Code and Standards and the Candidate Agreement · but not by the Membership Agreement"]]},{"t":"table","title":"Standard I(B) Independence and Objectivity","head":["Topic","Content"],"rows":[["Prohibition","Standard I(B) prohibits members and candidates from offering, soliciting, or accepting · any gift, benefit, or consideration that could reasonably be expected to compromise independence and objectivity"],["Client gifts","A gift received from a client, unlike a gift from an outside party seeking influence, · may be accepted as long as it is disclosed to the employer"],["Site visits","Best practice under Standard I(B) is for members and candidates to pay for their own commercial transportation · to issuer site visits rather than accept paid travel from the company being researched"],["Manager search","Under Standard I(B), a member serving on the hiring side of a manager search · may not solicit contributions to a favorite charity from firms seeking the mandate"],["Credit rating agency analysts","Standard I(B) applies to credit rating agency analysts, · who must abide by their agency's standards of conduct · to prevent undue influence from a sponsoring company during the rating process"]]},{"t":"def","term":"Standard I(C) Misrepresentation","text":"Standard I(C) prohibits members and candidates from knowingly making misrepresentations · relating to investment analysis, recommendations, actions, or other professional activities"}],"2":[{"t":"table","title":"Standard II(A) Material Nonpublic Information","head":["Topic","Content"],"rows":[["Prohibition","Standard II(A) prohibits members and candidates who possess material nonpublic information · from acting on it or causing others to act on it"],["Materiality","The reliability of the source of information is a relevant factor · in determining whether information is material under Standard II(A)"],["Mosaic theory","Under the mosaic theory, an analyst may use conclusions derived from public and nonmaterial nonpublic information · even if the same conclusion would have been material had it come directly from the company"],["Company will not disseminate","If a member cannot convince a company to publicly disseminate material nonpublic information it possesses, · the member should communicate it only to designated supervisory and compliance personnel · and must not take investment action on it"],["Firewall","An effective firewall requires that an employee, such as a research analyst who assists an investment banking deal, · remain on only one side of the information barrier at a time"]]},{"t":"table","title":"Standard II(B) Market Manipulation","head":["Topic","Content"],"rows":[["Prohibition","Standard II(B) prohibits practices that distort prices or artificially inflate trading volume · with the intent to mislead market participants"],["Information-based manipulation","A \"pump and dump\" scheme, where a holder spreads misleading positive information to inflate a price before selling, · is an example of information-based manipulation under Standard II(B)"],["Transaction-based manipulation","Securing a controlling or dominant position in a financial instrument · in order to exploit and manipulate the price of a related derivative · can constitute transaction-based manipulation"],["Indicator: canceled orders","Orders that are entered and then canceled before execution, intended to change the bid or offer price, · are listed in the guidance as a possible indicator of market manipulation"],["Indicator: coordination","Coordinated trading action by two or more traders in a market with a small number of participants · is listed as a possible indicator of market manipulation"],["Effect","Market manipulation is considered more likely to reduce investor confidence and raise risk premiums, · potentially harming a country's broader economic growth"]]}],"3":[{"t":"table","title":"Standard III(A) Loyalty, Prudence, and Care","head":["Topic","Content"],"rows":[["Duty","Standard III(A) requires members and candidates to act for the benefit of clients · and place client interests before those of their employer or themselves"],["Pension plan or trust","When managing assets for a pension plan or trust, · the duty of loyalty under Standard III(A) is owed to the ultimate beneficiaries · rather than to the entity that hired the manager"],["Soft dollars","A member who pays a higher brokerage commission than necessary to obtain research services (soft dollars), · without a corresponding benefit to the client, violates the duty of loyalty under Standard III(A)"],["Custody","Members and candidates with custody of client assets should submit itemized account statements · to clients at least quarterly"],["Conflicts","Members and candidates who cannot avoid a potential conflict · between their firm's interests and a client's interests · must provide clear and factual disclosure of the circumstances to the client"]]},{"t":"table","title":"Standard III(B) Fair Dealing","head":["Topic","Content"],"rows":[["Duty","Standard III(B) requires members and candidates to deal fairly and objectively with all clients · when providing investment analysis, making recommendations, or taking investment action"],["Premium service","Members and candidates may offer premium, more in-depth service to clients willing to pay for it, · provided the different service levels are disclosed and available to all clients"],["Oversubscribed new issue","If a new issue is oversubscribed, Standard III(B) guidance requires prorating the shares to suitable client accounts · and forgoing sales to the member's own or immediate family's accounts"],["Block trade","A recommended compliance practice under Standard III(B) is to give all client accounts participating in a block trade · the same execution price and the same commission"],["Dissemination","Members and candidates should make reasonable efforts to limit both the number of people aware of a pending recommendation · and the time between the decision and its dissemination"]]},{"t":"table","title":"Standard III(C) Suitability","head":["Topic","Content"],"rows":[["Inquiry","Standard III(C) requires members and candidates in an advisory relationship to make a reasonable inquiry · into a client's investment experience, risk and return objectives, and financial constraints · before making a recommendation or taking investment action"],["Investment policy statement","Best practice under Standard III(C) is to incorporate client information into a written investment policy statement · addressing risk tolerance, return requirements, and relevant investment limitations"]]}],"4":[{"t":"table","title":"Standard IV(A) Loyalty","head":["Topic","Content"],"rows":[["Duty","Standard IV(A) requires members and candidates to act for the benefit of their employer · and not deprive the employer of their skills, confidential information, or otherwise cause harm to the firm"],["Competing services","A member may not offer a service that competes with a service offered by the employer without the employer's consent"],["Resignation","After giving notice of resignation, members and candidates may provide the name of their new employer to clients · but must not provide new-employer contact information · or describe the new firm's services without the current employer's permission"],["Whistle-blowing","Under the whistle-blowing guidance, actions that would normally violate the duty to an employer, · such as copying records to preserve evidence, · may be justified when clearly aimed at protecting clients or market integrity rather than personal gain"]]},{"t":"table","title":"Standard IV(B) Additional Compensation Arrangements","head":["Topic","Content"],"rows":[["Written consent","Standard IV(B) requires members and candidates to obtain written consent from all relevant parties · before accepting gifts, benefits, or compensation · that competes with or might create a conflict with their employer's interest"],["Form of consent","Written consent can include any documentable form of communication, · such as an email that can be retrieved and documented"],["Client-contingent bonus","A client-contingent bonus arrangement, such as a paid vacation tied to portfolio performance, · must be disclosed to the employer · because it could create partiality toward that client's account"],["Disclosure","Disclosure should include the nature, approximate amount, and duration of any additional compensation arrangement · The party offering additional compensation to a member should acknowledge and confirm the details disclosed to the employer"],["Multiple employers","Members and candidates working part-time or on contract for multiple employers · should negotiate and address, during the hiring process, · the parameters around providing services to other, potentially competing employers"]]},{"t":"table","title":"Standard IV(C) Responsibilities of Supervisors","head":["Topic","Content"],"rows":[["Duty","Standard IV(C) requires members and candidates to make reasonable efforts · to ensure that anyone subject to their supervision or authority · complies with applicable laws, rules, regulations, and the Code and Standards"],["Inadequate compliance system","If a firm's compliance system is so inadequate that a member cannot discharge supervisory responsibilities, · the member should decline to accept supervisory responsibility until reasonable procedures are adopted"]]}],"5":[{"t":"table","title":"Standard V(A) Diligence and Reasonable Basis","head":["Topic","Content"],"rows":[["Duty","Standard V(A) requires members and candidates to have a reasonable and adequate basis, · supported by appropriate research and investigation, · for any investment analysis, recommendation, or action"],["Sources","Information or data sourced from blogs or social media may require a greater level of review · than information from more established research organizations"],["Third-party research","Members and candidates who rely on secondary or third-party research must make reasonable and diligent efforts · to determine that the research is sound before relying on it"],["Quantitative models","Individuals who develop new quantitative investment models must exhibit a higher level of diligence · than the individuals who ultimately use the models' output"],["External advisers","Standard V(A) requires the same level of diligence in selecting an external adviser or subadviser · as in reviewing an individual investment opportunity"],["Group research","A member on a research team may allow his name to remain on a group report reflecting a consensus view · that differs somewhat from his own opinion, · as long as he believes that consensus has a reasonable and adequate, independent, and objective basis"]]},{"t":"table","title":"Standard V(B) Communication with Clients and Prospective Clients","head":["Topic","Content"],"rows":[["Services and costs","Standard V(B) requires members and candidates to disclose to clients the nature of services provided · and information about the costs associated with those services"],["Risk changes","Members and candidates must notify clients when significant changes occur · in the risk characteristics of a security or investment strategy"],["Opinions","Standard V(B) requires that earnings estimates and forward-looking dividend expectations · be clearly identified as opinions rather than established facts"],["External advisers","Members and candidates must inform clients when their firm's investment process · involves the use of external advisers to manage portions of client assets"],["Inadequate disclosures","If a firm's standard disclosures are inadequate and cannot be corrected, · a member should document objections and take steps to dissociate from the activity"]]},{"t":"def","term":"Standard V(C) Record Retention","text":"Standard V(C) requires members and candidates to develop and maintain appropriate records · supporting their investment analyses, recommendations, actions, and related communications"}],"6":[{"t":"table","title":"Standard VI(A) Disclosure of Conflicts","head":["Topic","Content"],"rows":[["Duty","Standard VI(A) requires members and candidates to avoid or make full and fair disclosure of matters · that could reasonably be expected to impair their independence and objectivity · or interfere with duties to clients, prospective clients, and employers"],["Form of disclosure","Disclosures of conflicts of interest under Standard VI(A) must be prominent and communicated in plain language"],["Reportable conflicts","Reportable conflicts to employers include · ownership of stocks analyzed or recommended and participation on outside boards"],["Board service","Board service by investment personnel can create conflicts of interest, · including the risk of receiving material nonpublic information about the company"],["Compensation change","A change in a portfolio manager's compensation structure · that creates pressure inconsistent with clients' stated investment objectives · must be disclosed to clients under Standard VI(A)"],["Investment banking relationship","Best practice for an underwriter's research analyst covering a company · with which the firm has a long-standing investment banking relationship · is to disclose that special relationship in the research report"]]},{"t":"table","title":"Standard VI(B) Priority of Transactions","head":["Topic","Content"],"rows":[["Priority","Standard VI(B) requires that investment transactions for clients and employers have priority · over transactions in which a member or candidate is the beneficial owner"],["Family accounts","Family accounts that are also client accounts of the firm should be treated the same as other client accounts, · neither favored nor disadvantaged because of the family relationship"],["Blackout periods","Blackout or restricted periods are used to prevent investment personnel from front-running client trades · by trading for their own account before trading for clients"],["Preclearance","Preclearance procedures for personal trades are designed to identify possible conflicts of interest · before a trade is executed"],["Violation: hot IPO","A portfolio manager who routes hot IPO issues into a family member's account through a favored broker, · while clients are unable to participate, has violated Standard VI(B)"],["Violation: options position","A trading department head who closes a personal options position and establishes a new one · shortly after an internal negative research presentation, before the report reaches clients, · violates Standard VI(B)"]]}],"7":[{"t":"table","title":"Standard VII(A) Conduct as Participants in CFA Institute Programs","head":["Topic","Content"],"rows":[["Prohibition","Standard VII(A) prohibits members and candidates from engaging in conduct · that compromises the reputation or integrity of CFA Institute, the CFA designation, · or the integrity, validity, or security of CFA Institute programs"],["Not prohibited","Standard VII(A) does not prohibit candidates from discussing nonconfidential material with others, · including in study groups, while preparing for an exam"],["Violation: deferral request","Filing a fraudulent deferral request using an altered death certificate · to postpone a CFA exam date violates Standard VII(A)"],["Violation: exam grader","A member who serves as an exam grader and later tells candidate colleagues which specific question he graded · and how poorly candidates scored on it has violated Standard VII(A)"],["Violation: written notes","Bringing written notes into a computer-based testing center · and reviewing them during the exam violates Standard VII(A) · because it compromises the security and integrity of the exam"]]},{"t":"table","title":"Standard VII(B) Reference to CFA Institute, the CFA Designation, and the CFA Program","head":["Topic","Content"],"rows":[["Prohibition","Standard VII(B) prohibits members and candidates from misrepresenting or exaggerating the meaning or implications of · CFA Institute membership, holding the CFA designation, or candidacy in the CFA Program"],["Improper reference","A statement implying that CFA charterholders achieve superior investment performance results · is an example of an improper reference under Standard VII(B)"],["Lapsed membership","A former CFA Institute member whose membership has lapsed · may still state that they were a CFA Institute member in the past"],["Pseudonym","Using a pseudonym or fictitious online name tagged with the CFA designation to hide one's identity · while posting professional commentary is a misrepresentation under Standard VII(B)"]]}]};
